path circle4 = Circle(P, 6/7);
draw(circle1);
draw(circle2);
draw(circle3);
draw(circle4);
draw((0, 0)--(9, 0));
dot((2,0)); dot((5,0)); dot(P); dot((3, 0)); dot(origin);
path inversion = arc((0,0), 6, -30, 30);
draw(inversion, dashed);
label("$\Omega$", (6, 0) * dir(30), NW);
